import {backendConfig as config} from './backend-config.js';
import {ANALYTICS_STAGES,ANALYTICS_CAUSES} from './analytics.js';
const $=id=>document.getElementById(id),fmt=n=>Number(n||0).toLocaleString(),duration=s=>`${Math.floor((s||0)/60)}m ${Math.round((s||0)%60)}s`;
let signedIn=false,email='',request=0;
async function api(path,body,auth=false){const r=await fetch(config.apiBase+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});if(!r.ok){const e=new Error(auth&&[401,403].includes(r.status)?'Owner access required. Sign in with your authorized account.':'The request could not be completed. Please try again.');e.status=r.status;throw e;}return r.json();}
$('email-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('auth-status').textContent='Sending your sign-in code…';email=$('email').value.trim();try{await api('/owner/code',{email});$('code-form').hidden=false;$('auth-status').textContent='Check your email for the code. It expires shortly.';$('code').focus();}catch(err){$('auth-status').textContent=err.message;}finally{button.disabled=false;}});
$('code-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('/owner/verify',{email,code:$('code').value.trim()});signedIn=true;$('code').value='';await refresh(true);}catch(err){signedIn=false;$('auth-status').textContent=err.message;}finally{button.disabled=false;}});
function logout(){request++;signedIn=false;$('dashboard').hidden=true;$('login').hidden=false;$('signout').hidden=true;$('code-form').hidden=true;$('code').value='';$('auth-status').textContent='';for(const id of ['metrics','traffic','failures','duration','stages','outcomes','devices','recent','health'])$(id).replaceChildren();}
$('signout').onclick=()=>{const previous=signedIn;logout();if(previous)void api('/logout',{}).catch(()=>{});};
function text(tag,value,className){const n=document.createElement(tag);n.textContent=value;if(className)n.className=className;return n;}
function metric(label,value,caption){const n=text('div','','metric');n.append(text('span',label,'label'),text('strong',value),text('small',caption));return n;}
function bars(root,rows,max,{percent=false}={}){root.replaceChildren();if(!rows.length){root.append(text('p','No data yet'));return;}for(const r of rows){const line=text('div','','bar-row'),label=text('span',r.label),track=text('span','','track'),fill=text('span','','fill');if(r.note)label.append(text('small',r.note));fill.style.width=`${Math.max(0,Math.min(100,max?r.count/max*100:0))}%`;track.append(fill);line.append(label,track,text('span',percent?`${max?Math.round(r.count/max*100):0}%`:fmt(r.count),'count'));line.title=`${r.label}: ${fmt(r.count)} attempts`;root.append(line);}}
function traffic(rows){const root=$('traffic');root.replaceChildren();const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1040 230');svg.setAttribute('role','img');svg.setAttribute('aria-label','Daily visits and wins over the selected date range');const max=Math.max(1,...rows.map(r=>r.visits));
 const node=(tag,attrs)=>{const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);svg.append(e);return e;};
 for(let i=0;i<=4;i++){const y=18+i*44;node('line',{x1:45,x2:1015,y1:y,y2:y,stroke:'#2c382a'});node('text',{x:0,y:y+4}).textContent=fmt(Math.round(max*(1-i/4)));}
 for(const [key,color]of [['visits','#bfd797'],['wins','#d6a18d']]){const points=rows.map((r,i)=>`${45+i/Math.max(1,rows.length-1)*970},${194-r[key]/max*176}`).join(' ');node('polyline',{points,fill:'none',stroke:color,'stroke-width':2.5});}
 for(const i of [...new Set([0,Math.floor(rows.length/2),rows.length-1])])if(rows[i])node('text',{x:45+i/Math.max(1,rows.length-1)*970,y:222,'text-anchor':i===0?'start':i===rows.length-1?'end':'middle'}).textContent=rows[i].day.slice(5);
 root.append(svg);const legend=text('div','','legend');legend.append(text('span','● Visits'),text('span','● Wins'));root.append(legend);
}
export function renderDashboard(data){const s=data.summary;$('empty').hidden=!!s.visits;$('updated').textContent='Updated '+new Date(data.generatedAt).toLocaleString();const bounce=s.completedVisits?Math.round(s.bounces/s.completedVisits*100)+'%':'—',winRate=s.attempts?Math.round(s.wins/s.attempts*100)+'%':'—';$('metrics').replaceChildren(metric('Visits',fmt(s.visits),`${fmt(s.attempts)} attempts · ${fmt(s.playing)} open attempts`),metric('Bounce rate',bounce,`${fmt(s.bounces)} / ${fmt(s.completedVisits)} settled visits`),metric('Average active time',duration(s.avgActiveSeconds),`${duration(s.avgVisibleSeconds)} average visible-tab time`),metric('Escape rate',winRate,`${fmt(s.wins)} wins · ${fmt(s.losses)} losses`));$('health').textContent=`Median attempt: ${duration(s.medianAttemptSeconds)} · Average load: ${s.avgLoadMs==null?'—':(s.avgLoadMs/1000).toFixed(1)+'s'} · Loading errors: ${fmt(s.loadErrors)}`;traffic(data.daily);bars($('failures'),data.failures.map(r=>({label:ANALYTICS_CAUSES[r.cause]||'Objective failed',count:r.count})),Math.max(1,...data.failures.map(r=>r.count)));bars($('duration'),data.duration,Math.max(1,...data.duration.map(r=>r.count)));const stageMap=new Map(data.stages.map(s=>[s.key,s]));bars($('stages'),Object.entries(ANALYTICS_STAGES).map(([key,label])=>({label,count:stageMap.get(key)?.count||0,note:stageMap.get(key)?.count?`${fmt(stageMap.get(key).count)} attempts · avg ${duration(stageMap.get(key).seconds)} to reach`:null})),s.attempts,{percent:true});bars($('outcomes'),[{label:'Escaped',count:s.wins},{label:'Game over',count:s.losses},{label:'Left / inactive',count:s.abandoned},{label:'Still playing',count:s.playing},{label:'Load error',count:s.loadErrors}],Math.max(1,s.attempts));bars($('devices'),data.devices.map(r=>({label:r.device==='mobile'?'Mobile':'Desktop',count:r.visits,note:duration(r.seconds)+' average active time'})),s.visits);$('recent').replaceChildren();for(const r of data.recent||[]){const tr=document.createElement('tr'),stages=Object.keys(r.milestones||{});tr.append(text('td',new Date(r.started_at).toISOString().slice(0,16).replace('T',' ')),text('td',r.outcome==='playing'?(Date.now()-new Date(r.last_seen_at)>120000?'Left / inactive':'Playing'):r.outcome==='won'?'Escaped':ANALYTICS_CAUSES[r.cause]||r.outcome),text('td',duration(r.active_ms/1000)));const latest=stages.sort((a,b)=>(r.milestones[b]-r.milestones[a])||Object.keys(ANALYTICS_STAGES).indexOf(b)-Object.keys(ANALYTICS_STAGES).indexOf(a))[0];const progress=text('td',ANALYTICS_STAGES[latest]||'Loading');progress.append(text('small',`${stages.length} milestones reached`));progress.title=stages.map(k=>ANALYTICS_STAGES[k]).join('\n');tr.append(progress,text('td',r.saved));$('recent').append(tr);}if(!data.recent?.length){const tr=document.createElement('tr'),td=text('td','No attempts recorded yet');td.colSpan=5;tr.append(td);$('recent').append(tr);}}
async function refresh(signingIn=false){const current=++request;$('refresh').disabled=true;$('dashboard-status').textContent='';try{const data=await api('/insights',{days:Number($('days').value),environment:$('environment').value},true);if(current!==request)return;renderDashboard(data);if(data.truncated)$('dashboard-status').textContent='This view is limited to the newest 20,000 records. Select a shorter period for complete totals.';$('login').hidden=true;$('dashboard').hidden=false;$('signout').hidden=false;$('auth-status').textContent='';}catch(err){if(current!==request)return;if(signingIn)throw err;if([401,403].includes(err.status)){logout();$('auth-status').textContent='Your session expired or this account is not authorized. Sign in again.';}else $('dashboard-status').textContent=err.message;}finally{$('refresh').disabled=false;}}
$('refresh').onclick=()=>refresh();$('days').onchange=()=>refresh();$('environment').onchange=()=>refresh();
